import {
	Component,
	OnInit,
	Input,
	ViewChild,
	TemplateRef,
	ChangeDetectionStrategy
} from '@angular/core';
import {
	CalendarDateFormatter,
	CalendarEvent,
	CalendarView
} from 'angular-calendar';
import {
	addDays,
	subDays,
	startOfDay,
	isSameDay,
	isSameMonth
} from 'date-fns';
import { TranslateService } from '@ngx-translate/core';
import { Subject } from 'rxjs';

import { MeetingService } from './../../../../core/services/meeting.service';
import { HolidayService } from './../../../../core/services/holiday.service';
import { ProjectService } from './../../../../core/services/project.service';
import { DefectService } from './../../../../core/services/defect.service';
import { IncidentService } from './../../../../core/services/incident.service';
import { TaskService } from './../../../../core/services/task.service';
import { AuthenticationService } from './../../../../core/services/authentication.service';
import { TimesheetService } from './../../../../core/services/timesheet.service';
import { DashboardService } from './../../../../core/services/dashboard.service';
import { ToastrService } from 'ngx-toastr';
import Swal from 'sweetalert2';

import { colors } from './../../../../core/helpers/pm-helper';
import { CustomDateFormatter } from './../../../../core/helpers/custom-event-title-formatter.provider';
import * as moment from 'moment';

@Component({
	selector: 'app-calendar-list',
	changeDetection: ChangeDetectionStrategy.OnPush,
	templateUrl: './calendar-list.component.html',
	styleUrls: ['./calendar-list.component.scss'],
	providers: [{
		provide: CalendarDateFormatter,
		useClass: CustomDateFormatter
	}]
})

export class CalendarListComponent implements OnInit {
	AllCalendarEvents: any;
	isCalendarLoaded: boolean = false;
	tasks: any;
	task: any;
	incidents: any;
	defects: any;
	holidays: any;
	meetings: any;
	loginUser: any;
	timeLogs: any;
	timerInterval: any;
	timerInterval1: any;
	startDateTime: any
	totalHours: any;
	totalMinutes: any;
	totalSeconds: any;
	showTimer = false;
	isTimerStarted = false;
	view: CalendarView = CalendarView.Month;
	CalendarView = CalendarView;
	viewDate: Date = new Date();
	refresh: Subject<any> = new Subject();
	events: CalendarEvent[] = this.AllCalendarEvents;
	activeDayIsOpen: boolean = true;


	constructor(
		public translate: TranslateService,
		private projectService: ProjectService,
		private taskService: TaskService,
		private holidayService: HolidayService,
		private MeetingService: MeetingService,
		private authenticationService: AuthenticationService,
		private defectService: DefectService,
		private timesheetService: TimesheetService,
		private toastr: ToastrService,
		private incidentService: IncidentService
	) {
		this.authenticationService.loginUser.subscribe(x => this.loginUser = x);
	}

	ngOnInit() {
		this.getTasks();
		// this.getTimeLogs();
		// this.timerInterval1 = setInterval(() => {
		// 	if(this.loginUser) {
		// 		this.getTimeLogs(false);
		// 	}
		// }, 5000);
	}

	dayClicked({ date, events }: { date: Date; events: CalendarEvent[] }): void {
		if (isSameMonth(date, this.viewDate)) {
			if (
				(isSameDay(this.viewDate, date) && this.activeDayIsOpen === true) ||
				events.length === 0
			) {
				this.activeDayIsOpen = false;
			} else {
				this.activeDayIsOpen = true;
			}
			this.viewDate = date;
		}
	}

	addEvent(tasks): void {
		this.events = tasks;
		this.isCalendarLoaded = true;
		this.refreshView();
	}

	refreshView(): void {
		this.refresh.next();
	}

	setView(view: CalendarView) {
		this.view = view;
	}

	closeOpenMonthViewDay() {
		this.activeDayIsOpen = false;
	}

	getTasks() {
		this.taskService.getCalendarTasks().subscribe(
			data => {
				this.tasks = data;
                this.setCalendarData();
				// this.getDefects();
			});
	}

	getDefects() {
		this.defectService.getDefectForCalendar()
			.subscribe(
				data => {
					this.defects = data;
					this.getIncidents();
				});
	}

	getIncidents() {
		this.incidentService.getIncidentForCalendar()
			.subscribe(
				data => {
					this.incidents = data;
					this.getMeetings();
				});
	}

	getMeetings() {
		this.MeetingService.getCalendarMeetings().subscribe(
			data => {
				this.meetings = data;
				this.getHolidays();
			});
	}

	getHolidays() {
		this.holidayService.yearAllHolidays(new Date().getFullYear()).subscribe(
			data => {
				this.holidays = data;
				this.setCalendarData();
			});
	}

	setCalendarData() {
		let eventsAll = [];
		this.tasks.forEach(element => {
			eventsAll.push({
                start: subDays((new Date(element.start_time)), 0),
				end: addDays(new Date(element.end_time), 0),
				title: element.user_name+'<br>'+element.title + '<br>- '+element.start_time+ ' - '+element.end_time,
				color: colors.blue,
				allDay: false
			});
		});

		// this.defects.forEach(element => {
		// 	eventsAll.push({
		// 		start: subDays(startOfDay(new Date(element.start_date)), 0),
		// 		end: addDays(new Date(element.end_date), 0),
		// 		title: element.generated_id + " - " + element.defect_name,
		// 		color: colors.orange,
		// 		allDay: true
		// 	});
		// });

		// this.incidents.forEach(element => {
		// 	eventsAll.push({
		// 		start: subDays(startOfDay(new Date(element.start_date)), 0),
		// 		end: addDays(new Date(element.end_date), 0),
		// 		title: element.generated_id + " - " + element.incident_name,
		// 		color: colors.purple,
		// 		allDay: true
		// 	});
		// });

		// this.meetings.forEach(element => {
		// 	eventsAll.push({
		// 		start: subDays(startOfDay(new Date(element.start_date)), 0),
		// 		end: addDays(new Date(element.end_date), 0),
		// 		title: element.generated_id + " - " + element.title,
		// 		color: colors.yellow,
		// 		allDay: true
		// 	});
		// });

		// this.holidays.forEach(element => {
		// 	eventsAll.push({
		// 		start: startOfDay(new Date(element.date)),
		// 		title: this.translate.instant('holidays.title') + " - " + element.event_name,
		// 		color: {
		// 			primary: element.color,
		// 			secondary: element.color
		// 		}
		// 	});
		// });

		this.addEvent(eventsAll);
		this.AllCalendarEvents = eventsAll;
	}


	loadTimer() {
		this.totalHours = "00";
		this.totalMinutes = "00";
		this.totalSeconds = "00";

		if((this.timeLogs && this.timeLogs.is_task_timer) && (this.timeLogs.reference_id == this.task.id)) {
			this.showTimer = true;
			this.isTimerStarted = this.timeLogs.is_task_timer;
			this.startDateTime = this.timeLogs.start_time;

			this.startTimer(false);
		}

		if(this.timeLogs && (this.timeLogs.is_defect_timer || this.timeLogs.is_incident_timer)) {
			this.showTimer = false;
		}

		if(!this.timeLogs) {
			this.showTimer = true;
		}
	}

	selectTask(){
		const taskListHTML = `
				<div class="form-group">
				<select id="taskSelect" class="form-control">
				<option value="" disabled selected>Select task</option>
				${this.tasks.map(task => `<option value="${task.id}">${task.name}</option>`).join('')}
				</select>
				</div>
			`;

			// Hiển thị popup
			Swal.fire({
			title: 'Select Task',
			html: `
				<form id="taskForm">
				<div class="row">
					<div class="col-md-12">
				${taskListHTML}
					</div>
				</div>
				</form>
			`,
			showCancelButton: true,
			confirmButtonText: 'Start',
			cancelButtonText: 'Cancel',
			focusConfirm: false,
			preConfirm: () => {
				const taskSelect = document.getElementById('taskSelect') as HTMLSelectElement;

				// Lấy giá trị được chọn từ dropdown
				const selectedTask = taskSelect.value;

				// Kiểm tra nếu không có task nào được chọn
				if (!selectedTask) {
				Swal.showValidationMessage('Please select task.');
				}

				// Trả về giá trị được chọn
				return selectedTask;
			}
			}).then((result) => {
				if (result.value) {
					const selectedTasks = result.value;
					console.log('Các task đã chọn:', selectedTasks);
					// Xử lý các task đã chọn ở đây
				}
			});
	}

	startTimer(isSaved = true) {
		if(isSaved) {
			if(this.timeLogs && (this.timeLogs.is_task_timer || this.timeLogs.is_defect_timer || this.timeLogs.is_incident_timer)) {
				this.toastr.error(this.translate.instant('timer_logs.error_messages.message1'), this.translate.instant('tasks.title'));
				return false;
			}
		}

		this.timerInterval = setInterval(() => {
			this.startTimerWatch();
		}, 5000);

		if(isSaved) {
			this.isTimerStarted = true;
			this.saveTimeLogs();
		}
	}

	startTimerWatch() {
		let time = this.startDateTime ? this.startDateTime : this.getDateTime();

		let endDate = new Date(),
			startDate = new Date(time),
			dateDiff = endDate.getTime() - startDate.getTime();

		let hours = Math.floor((dateDiff / 36e5) % 24),
			minutes = Math.floor((dateDiff / 6e4) % 60),
			seconds = Math.floor((dateDiff / 1e3) % 60);

		this.totalHours = hours < 10 ? "0" + hours : hours ,
		this.totalMinutes = minutes < 10 ? "0" + minutes: minutes,
		this.totalSeconds = seconds < 10 ? "0" + seconds : seconds;
	}

	getDateTime() {
		let date = new Date(),
			fullDate = date.getDate() < 10 ? "0" + date.getDate() :date.getDate(),
			months = date.getMonth() + 1 < 10 ? "0" + (date.getMonth() + 1) : date.getMonth() + 1,
			hours = date.getHours() < 10 ? "0" + date.getHours() : date.getHours(),
			minutes = date.getMinutes() < 10 ? "0" + date.getMinutes() : date.getMinutes(),
			seconds = date.getSeconds() < 10 ? "0" + date.getSeconds() : date.getSeconds();

		return date.getFullYear() + "-" + months + "-" + fullDate + " " + hours + ":" + minutes + ":" + seconds;
	}

	saveTimeLogs() {
		this.timesheetService.createTimeLog({
			"project_id": this.task.project_id,
			"reference_id": this.task.id,
			"is_task_timer": true,
			"is_defect_timer": false,
			"is_incident_timer": false,
			"start_time": moment(new Date()).format("YYYY-MM-DD HH:mm:ss")
		}).subscribe(data => {
			this.startDateTime = new Date();
		});
	}

	stopTimer(isSaved) {
		let endDate = new Date(),
			startDate = new Date(this.startDateTime),
			dateDiff = endDate.getTime() - startDate.getTime();

			let diffHrs = Math.floor((dateDiff % 86400000) / 3600000); // hours
			let diffMins = Math.round(((dateDiff % 86400000) % 3600000) / 60000);

			// --
			// Check
			if(diffMins < 1) {
				this.toastr.error(this.translate.instant('timer_logs.error_messages.message2'), this.translate.instant('timesheet.title'));
				isSaved = false;
				// this.setClearInterval();
				// return false;
			}

			if(this.getStartFutureDate(this.startDateTime, this.getDateTime()) > 720) {
				this.toastr.error(this.translate.instant('timer_logs.error_messages.message3'), this.translate.instant('timesheet.title'));
				isSaved = false;
				// this.setClearInterval();
				// return false;
			}

		this.deleteTimesheet(isSaved);
	}

	getStartFutureDate(startDate, endDate) {
        (startDate = new Date(startDate)), (endDate = new Date(endDate));

        let diff = (startDate.getTime() - endDate.getTime()) / 1e3;
        return (diff /= 60), Math.abs(Math.round(diff));
    }

	setClearInterval() {
		clearInterval(this.timerInterval);
		this.getTimeLogs();
		this.isTimerStarted = false;
		this.startDateTime = null;
	}

	saveTimesheet() {
		this.timesheetService.create({
			"project_id": this.task.project_id,
			"module_id": 2,
			"module_related_id": this.task.id,
			"start_time": moment(new Date(this.startDateTime)).format("YYYY-MM-DD HH:mm:ss"),
			"end_time": moment(new Date()).format("YYYY-MM-DD HH:mm:ss"),
		}).subscribe(data => {
			this.toastr.success(this.translate.instant('timesheet.messages.create'), this.translate.instant('timesheet.title'));
			this.setClearInterval();
		});
	}

	deleteTimesheet(isSaved) {
		this.timesheetService.deleteTimeLog(this.loginUser.id)
			.subscribe(data => {
				if(isSaved) {
					this.saveTimesheet();
				} else {
					this.setClearInterval();
				}
			});
	}

	getTimeLogs(isLoad = true) {
		this.timesheetService.getTimeLogs()
			.subscribe(
				data => {
					this.timeLogs = data;

					if(isLoad) {
						this.loadTimer();
					}
				});
	}
}
